"""Merge/split suggestions: generated by a job, decided (accept/reject) by short transactions."""
from datetime import datetime, UTC

import numpy as np
from pydantic import BaseModel, ConfigDict, Field
from sqlalchemy import func, insert, select, update

from reqcluster import embeddings
from reqcluster.config import get_settings
from reqcluster.db import session_scope
from reqcluster.domain import Job, ProviderName
from reqcluster.errors import Conflict, NotFound, Stale
from reqcluster.jobs import JobContext, get_runner
from reqcluster.llm.gateway import get_gateway
from reqcluster.llm.narrate import cluster_narrative
from reqcluster.ml import refine
from reqcluster.models import (
    AssignmentRow,
    AuditRow,
    ClusterRow,
    RequirementRow,
    RunRow,
    SuggestionRow,
)
from reqcluster.services.assignments import reassign
from reqcluster.services.sessions import _current_run


class SuggestParams(BaseModel):
    model_config = ConfigDict(extra="forbid")
    top_n_merges: int = Field(3, ge=0, le=50)
    top_n_splits: int = Field(3, ge=0, le=50)
    sim_threshold: float = Field(0.7, ge=0, le=1)
    spread_threshold: float = Field(0.3, ge=0)
    # only suggest edits that improve cluster separation; null lists every candidate (ranked)
    min_silhouette_delta: float | None = 0.0
    provider: ProviderName | None = None


class DecisionBody(BaseModel):
    model_config = ConfigDict(extra="forbid")
    actor: str = ""


class SuggestSummary(BaseModel):
    run_id: int
    n_merges: int
    n_splits: int


class SuggestionOut(BaseModel):
    id: int
    kind: str
    status: str
    payload: dict
    rationale: str
    provider: str
    created_at: datetime
    stale: bool


class AuditOut(BaseModel):
    id: int
    action: str
    actor: str
    details: dict
    created_at: datetime


def _out(row: SuggestionRow, run: RunRow) -> SuggestionOut:
    return SuggestionOut(id=row.id, kind=row.kind, status=row.status, payload=row.payload,
                         rationale=row.rationale, provider=row.provider,
                         created_at=row.created_at, stale=row.edit_seq != run.edit_seq)


def start(sid: int, params: SuggestParams) -> Job:
    with session_scope() as s:
        _current_run(s, sid)
    return get_runner().submit("suggest", sid, lambda ctx: _run(ctx, sid, params),
                               params.model_dump())


def _run(ctx: JobContext, sid: int, p: SuggestParams) -> SuggestSummary:
    seed = get_settings().seed
    with session_scope() as s:
        run = _current_run(s, sid)
        rid, edit_seq = run.id, run.edit_seq
        rows = s.execute(select(RequirementRow.id, RequirementRow.text, AssignmentRow.cluster_id)
                         .join(AssignmentRow, AssignmentRow.requirement_id == RequirementRow.id)
                         .where(AssignmentRow.run_id == rid)
                         .order_by(RequirementRow.ordinal)).all()
        names = {c.cluster_id: c.label for c in s.scalars(
            select(ClusterRow).where(ClusterRow.run_id == rid))}
    req_ids = [r[0] for r in rows]
    labels = np.array([r[2] for r in rows], dtype=np.int64)
    ctx.progress(0.1, "embedding")
    emb = embeddings.embed([r[1] for r in rows])
    with np.load(get_settings().runs_dir / f"{rid}.npz") as z:
        x10 = z["x10"]
    ctx.check_cancel()
    merges = refine.suggest_merges(emb, x10, labels, p.top_n_merges, p.sim_threshold, seed,
                                  p.min_silhouette_delta)
    splits = refine.suggest_splits(emb, x10, labels, p.top_n_splits, p.spread_threshold, seed,
                                  p.min_silhouette_delta)

    gw = get_gateway()
    out: list[dict] = []
    for m in merges:
        pay = dict(m.__dict__)
        r = cluster_narrative(gw, "merge", p.provider,
                              cluster_a_label=names.get(m.cluster_a, str(m.cluster_a)),
                              cluster_b_label=names.get(m.cluster_b, str(m.cluster_b)),
                              centroid_similarity=m.centroid_similarity,
                              silhouette_delta=m.silhouette_delta,
                              coherence_a=m.coherence_a, coherence_b=m.coherence_b)
        out.append({"kind": "merge", "payload": pay, "rationale": str(r.output),
                    "provider": r.provider})
    for sp in splits:
        members = np.where(labels == sp.cluster_id)[0]
        pay = dict(sp.__dict__)
        # sub_labels follow the member order above, so accept can apply them without re-running ML
        pay["assignment"] = {str(req_ids[i]): int(v) for i, v in zip(members, sp.sub_labels, strict=True)}
        r = cluster_narrative(gw, "split", p.provider,
                              cluster_label=names.get(sp.cluster_id, str(sp.cluster_id)),
                              bimodality_score=sp.bimodality_score,
                              bic_improvement=sp.bic_improvement,
                              spread_score=sp.spread_score,
                              sub_cluster_sizes=sp.sub_cluster_sizes)
        out.append({"kind": "split", "payload": pay, "rationale": str(r.output),
                    "provider": r.provider})
        ctx.check_cancel()

    with session_scope() as s:
        # rejected, not deleted: sqlite reuses max ids, which would alias ids clients still hold
        s.execute(update(SuggestionRow).where(SuggestionRow.run_id == rid,
                                              SuggestionRow.status == "pending")
                  .values(status="rejected", decided_at=datetime.now(UTC)))
        if out:
            s.execute(insert(SuggestionRow),
                      [{"run_id": rid, "edit_seq": edit_seq, **o} for o in out])
    return SuggestSummary(run_id=rid, n_merges=len(merges), n_splits=len(splits))


def list_suggestions(sid: int, status: str | None = None) -> list[SuggestionOut]:
    with session_scope() as s:
        run = _current_run(s, sid)
        q = select(SuggestionRow).where(SuggestionRow.run_id == run.id).order_by(SuggestionRow.id)
        if status:
            q = q.where(SuggestionRow.status == status)
        return [_out(r, run) for r in s.scalars(q)]


def _load(s, sid: int, suggestion_id: int) -> tuple[SuggestionRow, RunRow]:
    row = s.get(SuggestionRow, suggestion_id)
    run = s.get(RunRow, row.run_id) if row else None
    if row is None or run.session_id != sid:
        raise NotFound(f"suggestion {suggestion_id} not found")
    if _current_run(s, sid).id != run.id:
        raise Stale("suggestion belongs to an older clustering run")
    if row.status != "pending":
        raise Conflict(f"suggestion {suggestion_id} is already {row.status}")
    if row.edit_seq != run.edit_seq:
        raise Stale("suggestion is stale: clusters changed since it was generated")
    job = get_runner().latest(sid, ("cluster", "recluster"))
    if job is not None and job.status in ("queued", "running"):
        raise Conflict("a clustering job is running for this session")
    return row, run


def decide(sid: int, suggestion_id: int, accept: bool, actor: str = "") -> SuggestionOut:
    with session_scope() as s:
        row, run = _load(s, sid, suggestion_id)
        pay = row.payload
        if accept:
            if row.kind == "merge":
                a, b = pay["cluster_a"], pay["cluster_b"]
                ids = s.scalars(select(AssignmentRow.requirement_id).where(
                    AssignmentRow.run_id == run.id, AssignmentRow.cluster_id == b))
                moves = {i: a for i in ids}
            else:
                new = (s.scalar(select(func.max(ClusterRow.cluster_id))
                                .where(ClusterRow.run_id == run.id)) or 0) + 1
                moves = {int(k): new for k, v in pay["assignment"].items() if v == 1}
            reassign(s, run, moves, action=f"suggestion_{row.kind}", actor=actor,
                     details={"suggestion_id": row.id})
        else:
            s.add(AuditRow(run_id=run.id, action="suggestion_reject", actor=actor,
                           details={"suggestion_id": row.id}))
        row.status = "accepted" if accept else "rejected"
        row.decided_at = datetime.now(UTC)
        return _out(row, run)


def audit(sid: int) -> list[AuditOut]:
    with session_scope() as s:
        run = _current_run(s, sid)
        rows = s.scalars(select(AuditRow).where(AuditRow.run_id == run.id)
                         .order_by(AuditRow.id.desc()))
        return [AuditOut(id=r.id, action=r.action, actor=r.actor, details=r.details,
                         created_at=r.created_at) for r in rows]


class CoherenceOut(BaseModel):
    cluster_id: int
    coherence_score: float
    top_keywords: list[str]
    size: int
    assessment: str


def coherence(sid: int) -> list[CoherenceOut]:
    with session_scope() as s:
        run_id = _current_run(s, sid).id
        rows = s.execute(select(RequirementRow.text, AssignmentRow.cluster_id)
                         .join(AssignmentRow, (AssignmentRow.requirement_id == RequirementRow.id)
                               & (AssignmentRow.run_id == run_id))
                         .where(RequirementRow.session_id == sid)
                         .order_by(RequirementRow.ordinal)).all()
        kws = {c.cluster_id: list(c.keywords or []) for c in s.scalars(
            select(ClusterRow).where(ClusterRow.run_id == run_id))}
    X = embeddings.embed([r[0] for r in rows])
    labels = np.array([r[1] for r in rows])
    return [CoherenceOut(**d) for d in refine.score_all_clusters(X, labels, kws)]
